// find_best.cpp: a blank note can mean "no answer".
#include <iostream>
#include <vector>

// The first score above limit, or nullptr if there is none.
const int* first_above(const std::vector<int>& scores, int limit) {
    for (const int& s : scores) {
        if (s > limit) {
            return &s;
        }
    }
    return nullptr;
}

void report(const int* found) {
    if (found != nullptr) {
        std::cout << "found " << *found << '\n';
    } else {
        std::cout << "nobody\n";
    }
}

int main() {
    std::vector<int> scores{55, 72, 91, 68};
    report(first_above(scores, 70));
    report(first_above(scores, 95));
}

