// observer.cpp: a pointer that only looks, never owns.
#include <iostream>
#include <string>

class Robot {
public:
    Robot(std::string name, int battery) : name_{name}, battery_{battery} {}
    std::string name() const { return name_; }
    int battery() const { return battery_; }
    void charge() { battery_ = 100; }
private:
    std::string name_;
    int battery_;
};

// Looks at a robot, if there is one. Doesn't own it.
void inspect(const Robot* r) {
    if (r == nullptr) {
        std::cout << "no robot on the bench\n";
        return;
    }
    std::cout << r->name() << " at " << r->battery() << "%\n";
}

int main() {
    Robot bolt{"Bolt", 35};
    Robot* bench{nullptr};
    inspect(bench);
    bench = &bolt;
    inspect(bench);
    bench->charge();
    inspect(bench);
}

