// ref_vs_ptr.cpp: a nickname is glued on; a note can be rewritten.
#include <iostream>

int main() {
    int a{7};
    int b{9};
    int& nick{a};           // nickname for a, forever
    int* note{&a};          // note with a's address, for now
    nick = b;               // copies 9 INTO a (no re-gluing!)
    note = &b;              // rewrites the note: now it says b
    *note = 20;             // changes b
    std::cout << "a=" << a << " b=" << b << '\n';
}

