// What is on this card? The number, or - for an empty card.
std::string look(const std::unique_ptr<int>& card) {
    return card ? std::to_string(*card) : "-";
}

int main() {
    auto a{std::make_unique<int>(1)};
    std::unique_ptr<int> b;
    std::cout << 1 << ' ' << look(a) << ' ' << look(b) << '\n';
